using System;
using System.Drawing;
using System.Globalization;
using System.Linq;
using System.Windows.Forms;
namespace Aster {
class GreetingData {public string Title,DateLine,Hijri,Occasion;}
static class GreetingClock {
 public static string Salutation(int hour){return hour>=5&&hour<12?"Good morning":hour>=12&&hour<17?"Good afternoon":hour>=17&&hour<22?"Good evening":"A peaceful night";}
 public static string Name(string configured,string fallback){string value=string.IsNullOrWhiteSpace(configured)?fallback:configured;value=new string((value??"").Where(c=>!char.IsControl(c)).ToArray()).Trim();return value.Length==0?"friend":value.Substring(0,Math.Min(40,value.Length));}
 public static GreetingData Format(DateTimeOffset utc,WorkspaceOptions options,string fallback){DateTimeOffset now;string zone;if(options.RiyadhTime){now=utc.ToOffset(TimeSpan.FromHours(3));zone="Riyadh · UTC+03:00";}else{now=TimeZoneInfo.ConvertTime(utc,TimeZoneInfo.Local);zone="Windows local · UTC"+now.ToString("zzz",CultureInfo.InvariantCulture);}var d=new GreetingData{Title=Salutation(now.Hour)+", "+Name(options.DisplayName,fallback)+".",DateLine=now.ToString("dddd, dd MMMM yyyy",CultureInfo.InvariantCulture)+"  ·  "+now.ToString("dd/MM/yyyy",CultureInfo.InvariantCulture)+"  ·  "+now.ToString(options.Clock24?"HH:mm:ss":"hh:mm:ss tt",CultureInfo.InvariantCulture)+"  ·  "+zone,Hijri="",Occasion="Make a little room for something good today."};return d;}
}
partial class MainWindow {
 Label greetingTitle,greetingDate,greetingHijri,greetingOccasion;Timer greetingTimer;
 void SetupGreeting(){greetingTimer=new Timer{Interval=1000};greetingTimer.Tick+=(s,e)=>{RefreshDailyPicture();RefreshGreeting();};greetingTimer.Start();RefreshDailyPicture();FormClosed+=(s,e)=>greetingTimer.Dispose();}
 void RefreshGreeting(){if(greetingTitle==null||greetingTitle.IsDisposed)return;var value=GreetingClock.Format(DateTimeOffset.UtcNow,preferences,Environment.UserName);greetingTitle.Text=value.Title;greetingDate.Text=value.DateLine;greetingHijri.Text=value.Hijri;greetingOccasion.Text=value.Occasion;}
 Control BuildGreetingHero(){var hero=new AuroraHeader{ThemeName=preferences.PlayTheme,Dock=DockStyle.Fill,Margin=new Padding(0,0,12,14),Padding=new Padding(20,8,14,8)};var art=new PictureBox{Dock=DockStyle.Right,Width=76,Image=DailyArt.Render(66,CurrentPictureNumber()),SizeMode=PictureBoxSizeMode.CenterImage,BackColor=Color.Transparent};bannerPicture=art;hero.Controls.Add(art);var rows=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=1,RowCount=4,BackColor=Color.Transparent};foreach(int height in new[]{42,27,24,25})rows.RowStyles.Add(new RowStyle(SizeType.Absolute,height));hero.Controls.Add(rows);rows.BringToFront();greetingTitle=GreetingLabel(20,Color.White);greetingTitle.Font=new Font("Segoe UI",20,FontStyle.Bold);greetingDate=GreetingLabel(9,Color.FromArgb(203,217,237));greetingHijri=GreetingLabel(10,Color.FromArgb(206,187,255));greetingOccasion=GreetingLabel(10,Color.FromArgb(123,230,208));rows.Controls.Add(greetingTitle,0,0);rows.Controls.Add(greetingDate,0,1);rows.Controls.Add(greetingHijri,0,2);rows.Controls.Add(greetingOccasion,0,3);RefreshGreeting();return hero;}
 Label GreetingLabel(int size,Color color){return new Label{Dock=DockStyle.Fill,BackColor=Color.Transparent,ForeColor=color,Font=new Font("Segoe UI",size),AutoEllipsis=true,UseMnemonic=false,TextAlign=ContentAlignment.MiddleLeft,Margin=new Padding(0)};}
 void AddGreetingPreferences(FlowLayoutPanel flow){flow.Controls.Add(new Label{Text="Your daily welcome",AutoSize=true,Font=new Font("Segoe UI",22,FontStyle.Bold)});flow.Controls.Add(new Label{Text="Choose your name and clock for the Summary greeting.",AutoSize=true,ForeColor=muted,Margin=new Padding(0,8,0,12)});var name=new TextBox{Width=310,MaxLength=40,Text=preferences.DisplayName??""};flow.Controls.Add(new Label{Text="Display name (leave blank to use your Windows username)",AutoSize=true});flow.Controls.Add(name);var riyadh=new CheckBox{Text="Use Riyadh time (UTC+03:00); otherwise use Windows local time",AutoSize=true,Checked=preferences.RiyadhTime};flow.Controls.Add(riyadh);var clock24=new CheckBox{Text="24-hour clock",AutoSize=true,Checked=preferences.Clock24};flow.Controls.Add(clock24);var save=Button("Save greeting preferences");save.Click+=(s,e)=>{preferences.DisplayName=name.Text.Trim();preferences.RiyadhTime=riyadh.Checked;preferences.Clock24=clock24.Checked;SavePreferences();RefreshGreeting();save.Text="Saved · see Summary";};flow.Controls.Add(save);flow.Controls.Add(new Label{Text="",Height=20});}
}
}

